            curr_r, curr_c = stack.pop()
            pos = (curr_r, curr_c)
            if pos in visited:
                continue
            visited.add(pos)
            comp.add(pos)

            # Check 4 neighbors
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < 7 and 0 <= nc < 24:
